<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/classes/GreenPortalDatabase.php';
require_once dirname(__DIR__).'/classes/AssistenteAplicacaoService.php';

function cliArg(string $key,string $default=''):string{foreach($GLOBALS['argv'] as $arg)if(str_starts_with($arg,'--'.$key.'='))return substr($arg,strlen($key)+3);return $default;}
function tableExists(PDO $db,string $table):bool{$q=$db->prepare("SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?");$q->execute([$table]);return (bool)$q->fetchColumn();}
function hashRows(array $rows,array $fields):string{usort($rows,fn($a,$b)=>strcmp((string)($a[$fields[0]]??''),(string)($b[$fields[0]]??'')));$data=[];foreach($rows as $row){$line=[];foreach($fields as $field)$line[]=(string)($row[$field]??'');$data[]=$line;}return hash('sha256',json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));}
function createProcedure(PDO $db,string $name,string $sql):void{$db->exec('DROP PROCEDURE IF EXISTS `'.$name.'`');$db->exec($sql);}
function registerTargetAudit(PDO $db,array $item):void{if(!tableExists($db,'registros_migracao'))return;$sql="CREATE PROCEDURE sp_ia_prompts_registrar_migracao(IN q INT,IN h INT,IN c INT,IN hf CHAR(64),IN hc CHAR(64),IN d JSON) BEGIN DELETE FROM registros_migracao WHERE codigo_migracao='REPLICACAO_PROMPTS_IA'; INSERT INTO registros_migracao(codigo_migracao,origem,destino,tipo,versao,status,quantidade_registros,iniciada_em,concluida_em,detalhes) VALUES('REPLICACAO_PROMPTS_IA','gmodelo_dbp.ia_prompts','ia_prompts','DADOS','1.0.0','CONCLUIDA',q,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,d); END";createProcedure($db,'sp_ia_prompts_registrar_migracao',$sql);$s=$db->prepare('CALL sp_ia_prompts_registrar_migracao(?,?,?,?,?,?)');$s->execute([(int)($item['prompts']??0),(int)($item['historico']??0),(int)($item['config']??0),(string)($item['hash_destino']??''),(string)($item['hash_config_destino']??''),json_encode($item,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);$s->closeCursor();}

$env=GreenPortalDatabase::env();$source=GreenPortalDatabase::connect($env,'gmodelo_dbp','GPT');$central=GreenPortalDatabase::connect($env,'guniversal_dbp','GUNIVERSAL');$info=GreenPortalDatabase::connect($env,'information_schema','GPT');$requested=trim(cliArg('target'));$requestId=(int)cliArg('solicitacao','0');$targets=$requested===''||$requested==='*'?$central->query("SELECT DISTINCT banco_novo FROM empresa_migracao_config WHERE banco_novo<>'' ORDER BY banco_novo")->fetchAll(PDO::FETCH_COLUMN):[$requested];
$promptFields=['codigo','nome_pt','nome_en','nome_es','prompt_pt','prompt_en','prompt_es','versao','ativo'];$prompts=$source->query('SELECT codigo,nome_pt,nome_en,nome_es,prompt_pt,prompt_en,prompt_es,versao,ativo,alterado_em FROM ia_prompts ORDER BY codigo')->fetchAll(PDO::FETCH_ASSOC);$history=$source->query('SELECT p.codigo,h.versao_anterior,h.versao_nova,h.prompt_pt_anterior,h.prompt_en_anterior,h.prompt_es_anterior,h.prompt_pt_novo,h.prompt_en_novo,h.prompt_es_novo,h.alterado_em FROM ia_prompts_historico h JOIN ia_prompts p ON p.codprompt=h.codprompt ORDER BY h.codhistorico')->fetchAll(PDO::FETCH_ASSOC);$configs=$source->query('SELECT chave,valor,descricao FROM ia_assistente_config ORDER BY chave')->fetchAll(PDO::FETCH_ASSOC);$sourcePromptHash=hashRows($prompts,$promptFields);$sourceConfigHash=hashRows($configs,['chave','valor','descricao']);$result=['fonte'=>'gmodelo_dbp','prompts_fonte'=>count($prompts),'historico_fonte'=>count($history),'config_fonte'=>count($configs),'hash_fonte'=>$sourcePromptHash,'hash_config_fonte'=>$sourceConfigHash,'alvos'=>[],'gerado_em'=>date('c')];
$promptProcedure="CREATE PROCEDURE sp_ia_prompts_replicar(IN c VARCHAR(120),IN npt VARCHAR(255),IN nen VARCHAR(255),IN nes VARCHAR(255),IN ppt TEXT,IN pen TEXT,IN pes TEXT,IN v INT,IN a TINYINT,IN dt DATETIME) BEGIN INSERT INTO ia_prompts(codigo,nome_pt,nome_en,nome_es,prompt_pt,prompt_en,prompt_es,versao,ativo,alterado_por,alterado_em) VALUES(c,npt,nen,nes,ppt,pen,pes,v,a,NULL,dt) ON DUPLICATE KEY UPDATE nome_pt=VALUES(nome_pt),nome_en=VALUES(nome_en),nome_es=VALUES(nome_es),prompt_pt=VALUES(prompt_pt),prompt_en=VALUES(prompt_en),prompt_es=VALUES(prompt_es),versao=VALUES(versao),ativo=VALUES(ativo),alterado_por=NULL,alterado_em=VALUES(alterado_em); END";
$historyProcedure="CREATE PROCEDURE sp_ia_historico_replicar(IN c VARCHAR(120),IN va INT,IN vn INT,IN ppa LONGTEXT,IN pea LONGTEXT,IN psa LONGTEXT,IN ppn LONGTEXT,IN pen LONGTEXT,IN psn LONGTEXT,IN u BIGINT,IN dt DATETIME) BEGIN DELETE h FROM ia_prompts_historico h JOIN ia_prompts p ON p.codprompt=h.codprompt WHERE p.codigo=c AND h.versao_anterior=va AND h.versao_nova=vn; INSERT INTO ia_prompts_historico(codprompt,versao_anterior,versao_nova,prompt_pt_anterior,prompt_en_anterior,prompt_es_anterior,prompt_pt_novo,prompt_en_novo,prompt_es_novo,alterado_por,alterado_em) SELECT codprompt,va,vn,ppa,pea,psa,ppn,pen,psn,u,dt FROM ia_prompts WHERE codigo=c LIMIT 1; END";
$configProcedure="CREATE PROCEDURE sp_ia_config_replicar(IN c VARCHAR(120),IN v TEXT,IN d VARCHAR(500)) BEGIN INSERT INTO ia_assistente_config(chave,valor,descricao,alterado_em) VALUES(c,v,d,CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE valor=VALUES(valor),descricao=VALUES(descricao),alterado_em=CURRENT_TIMESTAMP; END";
foreach($targets as $targetName){$targetName=(string)$targetName;$item=['status'=>'IGNORADO','prompts'=>0,'config'=>0,'historico'=>0,'incluidos'=>0,'atualizados'=>0,'inalterados'=>0];$db=null;try{$q=$info->prepare('SELECT COUNT(*) FROM SCHEMATA WHERE SCHEMA_NAME=?');$q->execute([$targetName]);if(!(int)$q->fetchColumn()){$item['status']='BANCO_NAO_EXISTE';$result['alvos'][$targetName]=$item;continue;}$db=GreenPortalDatabase::connect($env,$targetName,'GPT');if(!tableExists($db,'ia_prompts')){$item['status']='SEM_ESTRUTURA_IA';$result['alvos'][$targetName]=$item;continue;}if(!(int)$db->query("SELECT COUNT(*) FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA=DATABASE() AND ROUTINE_NAME='sp_ia_prompt_obter'")->fetchColumn()){$item['status']='SEM_PROCEDURE_IA_PROMPT_OBTER';$result['alvos'][$targetName]=$item;continue;}createProcedure($db,'sp_ia_prompts_replicar',$promptProcedure);$hasUsers=tableExists($db,'usuarios');$technicalUserId=0;if($hasUsers){$technicalUserId=(int)$db->query("SELECT codusuario FROM usuarios WHERE ativo=1 AND (LOWER(userid)='admin' OR LOWER(userid)='administrador' OR LOWER(nome) LIKE '%migra%') ORDER BY codusuario LIMIT 1")->fetchColumn();if(!$technicalUserId)$technicalUserId=(int)$db->query('SELECT codusuario FROM usuarios WHERE ativo=1 ORDER BY codusuario LIMIT 1')->fetchColumn();}$hasHistory=tableExists($db,'ia_prompts_historico');if($hasHistory&&$technicalUserId)createProcedure($db,'sp_ia_historico_replicar',$historyProcedure);$hasConfig=tableExists($db,'ia_assistente_config');if($hasConfig)createProcedure($db,'sp_ia_config_replicar',$configProcedure);$old=[];foreach($db->query('SELECT codigo,nome_pt,nome_en,nome_es,prompt_pt,prompt_en,prompt_es,versao,ativo FROM ia_prompts') as $row)$old[$row['codigo']]=$row;$db->beginTransaction();foreach($prompts as $p){$same=isset($old[$p['codigo']])&&hashRows([$old[$p['codigo']]],$promptFields)===hashRows([$p],$promptFields);$s=$db->prepare('CALL sp_ia_prompts_replicar(?,?,?,?,?,?,?,?,?,?)');$s->execute([$p['codigo'],$p['nome_pt'],$p['nome_en'],$p['nome_es'],$p['prompt_pt'],$p['prompt_en'],$p['prompt_es'],$p['versao'],$p['ativo'],$p['alterado_em']]);$s->closeCursor();$item['prompts']++;if($same)$item['inalterados']++;elseif(isset($old[$p['codigo']]))$item['atualizados']++;else$item['incluidos']++;}if($hasHistory&&$technicalUserId)foreach($history as $h){$s=$db->prepare('CALL sp_ia_historico_replicar(?,?,?,?,?,?,?,?,?,?,?)');$s->execute([$h['codigo'],$h['versao_anterior'],$h['versao_nova'],$h['prompt_pt_anterior'],$h['prompt_en_anterior'],$h['prompt_es_anterior'],$h['prompt_pt_novo'],$h['prompt_en_novo'],$h['prompt_es_novo'],$technicalUserId,$h['alterado_em']]);$s->closeCursor();$item['historico']++;}elseif($hasHistory)$item['historico_observacao']='Nao replicado: usuario tecnico inexistente no destino.';if($hasConfig)foreach($configs as $c){$s=$db->prepare('CALL sp_ia_config_replicar(?,?,?)');$s->execute([$c['chave'],$c['valor'],$c['descricao']]);$s->closeCursor();$item['config']++;}$targetRows=$db->query('SELECT codigo,nome_pt,nome_en,nome_es,prompt_pt,prompt_en,prompt_es,versao,ativo FROM ia_prompts ORDER BY codigo')->fetchAll(PDO::FETCH_ASSOC);$targetConfigs=$hasConfig?$db->query('SELECT chave,valor,descricao FROM ia_assistente_config ORDER BY chave')->fetchAll(PDO::FETCH_ASSOC):[];$item['hash_fonte']=$sourcePromptHash;$item['hash_destino']=hashRows($targetRows,$promptFields);$item['hash_config_fonte']=$sourceConfigHash;$item['hash_config_destino']=hashRows($targetConfigs,['chave','valor','descricao']);$item['hash_igual']=$item['hash_fonte']===$item['hash_destino'];$item['hash_config_igual']=$item['hash_config_fonte']===$item['hash_config_destino'];$item['status']=($item['hash_igual']&&$item['hash_config_igual'])?'REPLICADO':'HASH_DIVERGENTE';$db->commit();if($requestId)try{AssistenteAplicacaoService::chamarProcedure($central,'sp_migracao_prompts_atualizar',[$requestId,$item['prompts'],$item['config'],$item['hash_destino'],json_encode($item,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);}catch(Throwable){} }catch(Throwable $ex){if($db instanceof PDO&&$db->inTransaction())$db->rollBack();$item['status']='ERRO';$item['erro']=$ex->getMessage();}$result['alvos'][$targetName]=$item;}
foreach($result['alvos'] as $auditTarget=>$auditItem)if(($auditItem['status']??'')==='REPLICADO')try{registerTargetAudit(GreenPortalDatabase::connect($env,(string)$auditTarget,'GPT'),$auditItem);}catch(Throwable $auditError){$result['alvos'][$auditTarget]['auditoria_status']='ERRO';$result['alvos'][$auditTarget]['auditoria_erro']=$auditError->getMessage();}
echo json_encode($result,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT),PHP_EOL;
